def shlex_split(s):
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        # Skip whitespace
        while i < n and s[i] in ' \t\n\r\f\v':
            i += 1

        if i >= n:
            break

        token = []
        while i < n:
            c = s[i]

            # Whitespace ends the token
            if c in ' \t\n\r\f\v':
                break

            # Single quote: everything literal until closing single quote
            if c == "'":
                i += 1  # skip opening quote
                while i < n and s[i] != "'":
                    token.append(s[i])
                    i += 1
                if i < n:
                    i += 1  # skip closing quote
                continue

            # Double quote: backslash escapes only backslash or double quote
            if c == '"':
                i += 1  # skip opening quote
                while i < n and s[i] != '"':
                    if s[i] == '\\':
                        if i + 1 < n and s[i + 1] in ('\\', '"'):
                            token.append(s[i + 1])
                            i += 2
                        else:
                            # backslash is literal
                            token.append('\\')
                            i += 1
                    else:
                        token.append(s[i])
                        i += 1
                if i < n:
                    i += 1  # skip closing quote
                continue

            # Backslash outside quotes: escapes next character
            if c == '\\':
                if i + 1 < n:
                    token.append(s[i + 1])
                    i += 2
                else:
                    # trailing backslash, just add it
                    token.append('\\')
                    i += 1
                continue

            # Regular character
            token.append(c)
            i += 1

        tokens.append(''.join(token))

    return tokens
