def shlex_split(s):
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        # Skip whitespace
        if s[i].isspace():
            i += 1
            continue

        token = []
        while i < n and not s[i].isspace():
            c = s[i]
            if c == "'":
                # Single quotes: everything literal until next single quote
                i += 1
                while i < n and s[i] != "'":
                    token.append(s[i])
                    i += 1
                if i < n:
                    i += 1  # skip closing single quote
            elif c == '"':
                # Double quotes: backslash escapes only backslash or double quote
                i += 1
                while i < n and s[i] != '"':
                    if s[i] == '\\':
                        if i + 1 < n and s[i + 1] in ('\\', '"'):
                            token.append(s[i + 1])
                            i += 2
                        else:
                            token.append('\\')
                            i += 1
                    else:
                        token.append(s[i])
                        i += 1
                if i < n:
                    i += 1  # skip closing double quote
            elif c == '\\':
                # Backslash escaping outside quotes: escapes next character
                if i + 1 < n:
                    token.append(s[i + 1])
                    i += 2
                else:
                    token.append('\\')
                    i += 1
            else:
                token.append(c)
                i += 1

        tokens.append(''.join(token))

    return tokens
